-- Пул предгенерированных раскладов для онбординга.
--
-- Зачем: новый пользователь получает первый расклад «в подарок» сразу после карты дня,
-- ДО заполнения профиля и без вызова AI (не тратим токены на неактивированную аудиторию).
-- Вопрос выбирается из фиксированного списка (кнопки в онбординге), вариант — случайный
-- из пула. Карты и позиции настоящие, интерпретации написаны заранее.
--
-- per_card_interpretations — JSON-массив из 3 строк (прошлое, настоящее, будущее),
-- порядок соответствует card_slugs. Пул расширяется добавлением строк без деплоя.
CREATE TABLE onboarding_spreads
(
    id                       BIGSERIAL PRIMARY KEY,
    question                 TEXT         NOT NULL,
    card_slugs               VARCHAR(64)  NOT NULL, -- 'maj01,maj07,maj21' — порядок = позиции расклада
    per_card_interpretations TEXT         NOT NULL, -- JSON-массив из 3 текстов по картам
    general_interpretation   TEXT         NOT NULL,
    is_active                BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_onboarding_spreads_question ON onboarding_spreads (question) WHERE is_active;

-- ═══════════════════════════════════════════════════════════════════════════
-- Вопрос 1: «Что меня ждёт в ближайшее время?»
-- ═══════════════════════════════════════════════════════════════════════════
INSERT INTO onboarding_spreads (question, card_slugs, per_card_interpretations, general_interpretation) VALUES
('Что меня ждёт в ближайшее время?', 'maj00,maj10,maj19',
 '["Шут в позиции прошлого говорит о недавнем шаге в неизвестность: вы уже начали что-то новое, даже если сами не придали этому значения.","Колесо Фортуны в настоящем — период, когда обстоятельства меняются сами собой. Не всё зависит от вас, и это сейчас не слабость, а подсказка: ловите поворот.","Солнце в будущем — одна из самых светлых карт колоды. Впереди ясность, прилив сил и результат, который будет заметен не только вам."]',
 'Расклад складывается удивительно цельно: недавняя смелость (Шут) уже запустила колесо перемен, и оно сейчас в движении — вы можете чувствовать это как лёгкую неопределённость. Карты советуют не пытаться всё контролировать: Колесо Фортуны работает на вас. Ближайшие недели принесут поворот к лучшему, а Солнце в позиции будущего обещает период, когда усилия начнут возвращаться радостью и конкретными результатами. Хорошее время, чтобы говорить «да» новым предложениям.'),

('Что меня ждёт в ближайшее время?', 'maj01,maj07,maj21',
 '["Маг в прошлом: у вас уже есть всё необходимое — навыки, связи, идеи. Недавно вы в этом убедились, даже если не назвали это своей заслугой.","Колесница в настоящем — момент движения и воли. Сейчас важно держать поводья: энергии много, и она просит направления.","Мир в будущем — карта завершения большого цикла. То, что вы сейчас разгоняете, придёт к ощутимому, законченному результату."]',
 'Сильная тройка действия: Маг дал вам инструменты, Колесница даёт скорость, а Мир обещает финал, которым можно будет гордиться. Ближайшее время — не про ожидание, а про завершение: у вас есть шанс довести до конца то, что давно тянется. Карты подсказывают: не распыляйтесь на несколько целей сразу — Колесница едет туда, куда смотрит возница. Выберите главное, и к концу цикла вы увидите результат, который закроет старый вопрос целиком.'),

('Что меня ждёт в ближайшее время?', 'maj17,maj03,maj06',
 '["Звезда в прошлом: недавно вы не потеряли надежду там, где было легко её потерять. Это уже изменило ваш внутренний курс.","Императрица в настоящем — время роста и заботы. Вокруг вас созревает то, что вы посадили: отношения, проекты, планы.","Влюблённые в будущем — впереди важный выбор сердцем. Это не обязательно про романтику: это про решение, которое нельзя принять чужой головой."]',
 'Очень тёплый расклад. Звезда говорит, что вы вошли в этот период с верой — и она была не напрасной. Сейчас Императрица окружает вас энергией созревания: не торопите события, им нужно немного времени, как саду. А впереди Влюблённые — выбор, который определит следующий этап. Карты советуют готовиться к нему уже сейчас: спросите себя честно, чего хотите именно вы, а не те, кто рядом. Когда момент придёт, ответ должен быть готов.'),

('Что меня ждёт в ближайшее время?', 'maj09,maj14,maj19',
 '["Отшельник в прошлом — период уединения или внутренней работы. Вы что-то важное поняли наедине с собой, и это понимание с вами.","Умеренность в настоящем — карта тонкой настройки. Сейчас жизнь просит не рывков, а баланса: понемногу, но каждый день.","Солнце в будущем — награда за терпение. Впереди период ясности, когда станет очевидно, ради чего всё было."]',
 'Расклад о созревании. Отшельник говорит: вы недавно прошли этап, который никто не видел, — тихий, внутренний, но решающий. Умеренность в настоящем подсказывает, что сейчас не время форсировать: смешивайте, пробуйте, выравнивайте — как вода точит камень. И тогда Солнце в позиции будущего раскроется в полную силу: ясность, признание, ощущение «всё было не зря». Ближайшее время благоволит спокойной последовательности больше, чем громким шагам.'),

('Что меня ждёт в ближайшее время?', 'maj02,maj10,maj17',
 '["Жрица в прошлом: интуиция уже подсказывала вам верное направление. Вспомните недавнее предчувствие — оно было точным.","Колесо Фортуны в настоящем — обстоятельства вокруг вас пришли в движение. Что-то меняется прямо сейчас, даже если внешне всё тихо.","Звезда в будущем — надежда, которая сбывается. Впереди период, когда желаемое начнёт обретать реальные очертания."]',
 'Мягкий и глубокий расклад. Жрица напоминает: вы уже знаете ответ на свой вопрос — он приходил к вам как предчувствие. Колесо Фортуны в настоящем говорит, что события ускорились, и часть из них разворачивается за кулисами вашей жизни. Звезда в будущем — очень добрый знак: то, на что вы почти боитесь надеяться, имеет реальные шансы сбыться. Карты советуют в ближайшее время доверять первому внутреннему отклику — он сейчас точнее любых расчётов.'),

('Что меня ждёт в ближайшее время?', 'maj08,maj11,maj21',
 '["Сила в прошлом: вы недавно справились с тем, что требовало не громкости, а выдержки. Эта победа тише, чем заслуживает, но она ваша.","Справедливость в настоящем — время, когда всё взвешивается. Решения, принятые сейчас, будут честными по отношению к вам — если вы будете честны с собой.","Мир в будущем — гармоничное завершение. Впереди точка, где усилия, отношения и планы сойдутся в цельную картину."]',
 'Расклад зрелости. Сила говорит, что у вас за плечами победа над собой — а это самый прочный фундамент. Справедливость в настоящем означает период оценки: жизнь сейчас подводит баланс, и он складывается в вашу пользу. Ничего не приукрашивайте и не преуменьшайте — просто будьте точны. Тогда Мир в будущем принесёт то редкое ощущение, когда всё на своих местах. Ближайшее время — про честные решения, которые окупятся сполна.'),

('Что меня ждёт в ближайшее время?', 'maj18,maj01,maj19',
 '["Луна в прошлом — период сомнений и неясности. Вы шли на ощупь, и это было утомительно, но туман уже рассеивается.","Маг в настоящем: сейчас у вас в руках все инструменты. Момент, когда из «не знаю как» рождается «попробую вот так».","Солнце в будущем — выход из тени. Впереди ясность и энергия, которых так не хватало в последнее время."]',
 'Расклад-восход. Луна в прошлом честно признаёт: было непросто — сомнения, недосказанность, ощущение, что идёте вслепую. Но Маг в настоящем меняет всё: сейчас вы впервые за долгое время способны действовать, а не гадать. Используйте это: один конкретный шаг сегодня стоит десяти планов. Солнце в будущем подтверждает — вы выходите на свет, и ближайшее время принесёт ту самую ясность, которой не хватало. Тёмная полоса действительно заканчивается.'),

('Что меня ждёт в ближайшее время?', 'maj04,maj06,maj10',
 '["Император в прошлом: вы недавно навели порядок — в делах, в голове или в отношениях. Эта структура сейчас держит вас.","Влюблённые в настоящем — вы стоите перед выбором или уже живёте в нём. Сердце и разум спорят, и это нормально.","Колесо Фортуны в будущем — перемены придут сами. Выбор, который вы сделаете сейчас, определит, какой стороной повернётся колесо."]',
 'Динамичный расклад. Император говорит: фундамент есть — вы уже выстроили опору, на которую можно ставить новое. Влюблённые в настоящем показывают точку выбора: возможно, вы разрываетесь между надёжным и желанным. Карты не выбирают за вас, но подсказывают: Колесо Фортуны в будущем придёт в движение в любом случае — вопрос лишь, по какой дороге вы его встретите. Ближайшее время потребует одного честного решения. Примите его сами, не по инерции.');

-- ═══════════════════════════════════════════════════════════════════════════
-- Вопрос 2: «Что мне важно понять о себе прямо сейчас?»
-- ═══════════════════════════════════════════════════════════════════════════
INSERT INTO onboarding_spreads (question, card_slugs, per_card_interpretations, general_interpretation) VALUES
('Что мне важно понять о себе прямо сейчас?', 'maj02,maj08,maj17',
 '["Жрица в прошлом: вы всегда знали о себе больше, чем позволяли себе признать. Ваша интуиция — не случайность, а способность.","Сила в настоящем: сейчас ваш главный ресурс — мягкая настойчивость. Вы приручаете обстоятельства не давлением, а терпением, и это работает.","Звезда в будущем: впереди период, когда вернётся вера в себя — не громкая, а спокойная и глубокая."]',
 'Карты говорят о вас неожиданно единодушно: ваша сила — тихая. Жрица напоминает, что вы чувствуете людей и ситуации точнее, чем большинство, но привыкли списывать это на совпадения. Сила в настоящем показывает: вы уже умеете справляться с трудным — без надрыва, изнутри. Главное, что стоит понять о себе сейчас: вам не нужно становиться кем-то другим, громче или жёстче. Звезда в будущем обещает: как только вы признаете собственную ценность, внешнее начнёт подстраиваться под это знание.'),

('Что мне важно понять о себе прямо сейчас?', 'maj12,maj14,maj21',
 '["Повешенный в прошлом: вы прошли период вынужденной паузы, который казался застоем. На самом деле вы смотрели на жизнь под новым углом.","Умеренность в настоящем: сейчас вы учитесь соединять противоположности в себе — и у вас получается лучше, чем вы думаете.","Мир в будущем: вы движетесь к внутренней целостности, когда разные части вашей жизни перестанут спорить друг с другом."]',
 'Глубокий расклад о взрослении души. Повешенный говорит: та пауза или задержка, которая вас раздражала, была не потерей времени — она развернула ваш взгляд. Умеренность в настоящем подсказывает главное: вы не обязаны выбирать между «или-или», ваш путь — «и то, и другое, в своей пропорции». Именно это стоит понять о себе: вы человек синтеза, а не крайностей. Мир в будущем обещает состояние, когда внутренние противоречия улягутся — и окажется, что они всегда были частями одного целого.'),

('Что мне важно понять о себе прямо сейчас?', 'maj09,maj01,maj19',
 '["Отшельник в прошлом: вы искали ответы в одиночестве — и нашли больше, чем ожидали. Этот опыт сделал вас самостоятельнее.","Маг в настоящем: пришло время понять — вы уже не ученик. Всё, что нужно для следующего шага, у вас в руках.","Солнце в будущем: впереди период, когда вы позволите себе быть заметным — и мир отреагирует теплом."]',
 'Расклад о выходе из тени. Отшельник показывает: период внутренних поисков завершён, вы собрали свою мудрость по крупицам. Маг в настоящем говорит прямо — хватит готовиться. Главное, что важно понять о себе сейчас: ощущение «я ещё не готов» устарело, оно из прошлого сезона вашей жизни. Вы готовы. Солнце в будущем подтверждает: как только вы начнёте действовать открыто, придут и признание, и радость. Ваша задача на ближайшее время — перестать прятать то, что умеете.'),

('Что мне важно понять о себе прямо сейчас?', 'maj05,maj06,maj14',
 '["Иерофант в прошлом: вы выросли на правилах и ожиданиях других людей — они дали опору, но местами стали тесны.","Влюблённые в настоящем: сейчас вы учитесь выбирать по-своему. Каждый такой выбор — маленькое освобождение.","Умеренность в будущем: впереди баланс между «как принято» и «как хочу я» — вы найдёте свою формулу."]',
 'Расклад о праве на собственный путь. Иерофант говорит: многое в вас — от учителей, семьи, среды. Это не плохо, но карты подсказывают: часть этих правил вы носите по привычке, а не по согласию. Влюблённые в настоящем показывают, что вы уже начали выбирать сердцем — и именно это сейчас главное понимание о себе: ваши желания не каприз, а компас. Умеренность в будущем обещает: вам не придётся ломать старое, чтобы жить по-своему, — вы соедините уважение к корням со свободой выбора.'),

('Что мне важно понять о себе прямо сейчас?', 'maj18,maj08,maj17',
 '["Луна в прошлом: вы через многое прошли в сумерках — сомнения, тревоги, недосказанность. И всё же не свернули.","Сила в настоящем: то, что вы называете усталостью, на самом деле выдержка. Вы сильнее, чем себе рассказываете.","Звезда в будущем: тревога уступит место спокойной надежде. Вы научитесь доверять себе так же, как доверяют вам другие."]',
 'Честный и добрый расклад. Луна в прошлом признаёт: было темно, и вы шли без гарантий — это утомляет сильнее любой работы. Но Сила в настоящем переворачивает картину: вы не «еле держитесь», вы держитесь — а это разные вещи. Главное понимание о себе сейчас: ваша тревожность — не слабость, а цена внимательности к жизни, и её можно приручить. Звезда в будущем обещает период, когда внутренний шум стихнет и вы услышите собственный голос — спокойный и уверенный.'),

('Что мне важно понять о себе прямо сейчас?', 'maj00,maj02,maj10',
 '["Шут в прошлом: в вас всегда жила готовность начать заново — вы делали это не раз, даже когда было страшно.","Жрица в настоящем: сейчас внутренний голос говорит с вами особенно ясно. Вопрос лишь в том, слушаете ли вы.","Колесо Фортуны в будущем: перемены уже в пути. Ваша открытость новому — именно тот ключ, который их запустит."]',
 'Расклад о доверии себе. Шут напоминает: ваша способность начинать с чистого листа — редкий дар, а не легкомыслие, как вам, возможно, говорили. Жрица в настоящем подсказывает главное: прямо сейчас вы уже чувствуете, куда вас тянет, — это чувство и есть ответ. Важно понять о себе: вам не нужно больше информации, вам нужно больше доверия к тому, что вы уже знаете. Колесо Фортуны в будущем обещает: стоит сделать шаг в сторону этого внутреннего «да» — и события начнут складываться сами.'),

('Что мне важно понять о себе прямо сейчас?', 'maj03,maj11,maj19',
 '["Императрица в прошлом: вы много отдавали — заботой, временем, силами. Вокруг вас выросло то, что без вас бы не выросло.","Справедливость в настоящем: пришло время честного баланса — сколько вы отдаёте и сколько возвращается к вам.","Солнце в будущем: впереди период, когда забота о себе перестанет казаться эгоизмом и начнёт приносить плоды."]',
 'Расклад о ценности себя. Императрица показывает: вы из тех, кто растит — людей, дела, отношения. Это прекрасно, но Справедливость в настоящем задаёт неудобный вопрос: а к вам это тепло возвращается в той же мере? Главное понимание о себе сейчас: ваша щедрость — сила только тогда, когда у неё есть границы. Вы имеете право на «нет» и на заботу о себе без чувства вины. Солнце в будущем обещает: как только баланс восстановится, энергии станет больше — и на себя, и на любимых людей.'),

('Что мне важно понять о себе прямо сейчас?', 'maj07,maj12,maj21',
 '["Колесница в прошлом: вы привыкли добиваться — напором, скоростью, контролем. Это приносило победы, но дорого стоило.","Повешенный в настоящем: жизнь предлагает вам новый навык — отпускать. Не сдаваться, а именно отпускать то, что не требует борьбы.","Мир в будущем: впереди целостность, в которой сила и мягкость перестанут быть противоположностями."]',
 'Расклад о новой ступени. Колесница говорит: вы боец, и ваши победы — настоящие. Но Повешенный в настоящем приносит непривычную мысль: следующий уровень берётся не штурмом, а умением на время ослабить хватку. Главное, что стоит понять о себе: контроль был вашей защитой, но сейчас он местами мешает получать. Попробуйте в одном деле просто позволить событиям идти — как эксперимент. Мир в будущем обещает: именно так вы придёте к состоянию, где не нужно постоянно воевать, чтобы чувствовать себя живым.');

-- ═══════════════════════════════════════════════════════════════════════════
-- Вопрос 3: «Куда мне направить энергию, чтобы всё сложилось?»
-- ═══════════════════════════════════════════════════════════════════════════
INSERT INTO onboarding_spreads (question, card_slugs, per_card_interpretations, general_interpretation) VALUES
('Куда мне направить энергию, чтобы всё сложилось?', 'maj01,maj03,maj19',
 '["Маг в прошлом: вы уже собрали инструменты — знания, опыт, умения. Подготовительный этап завершён.","Императрица в настоящем: сейчас энергию стоит направить на выращивание, а не на завоевание. Поливайте то, что уже посажено.","Солнце в будущем: то, что вы сейчас бережно растите, расцветёт заметно и щедро."]',
 'Ответ карт удивительно земной: не начинайте новое — укрепляйте начатое. Маг говорит, что этап сбора инструментов позади, у вас всё есть. Императрица в настоящем показывает точку приложения силы: одно-два дела или отношения, которые уже живут в вашей жизни и просят внимания. Именно туда — время, заботу, регулярность. Не распыляйтесь на десять направлений. Солнце в будущем обещает: то, что вы выберете растить, даст урожай, который окупит всё вложенное — и станет видимым для окружающих.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj07,maj08,maj21',
 '["Колесница в прошлом: разгон уже взят — вы недавно сдвинули с места то, что долго стояло.","Сила в настоящем: сейчас энергия нужна не для рывка, а для удержания курса. Побеждает не самый быстрый, а самый устойчивый.","Мир в будущем: на этом пути вас ждёт завершение большого этапа — цельное и заслуженное."]',
 'Карты отвечают чётко: энергию — в постоянство. Колесница показывает, что старт состоялся, движение есть. Теперь Сила в настоящем меняет тактику: главный враг сейчас не преграды, а соблазн всё бросить на середине или отвлечься на новое блестящее. Направьте силы на ежедневное, пусть небольшое, продвижение в главном деле — по шагу, но без пропусков. Мир в будущем подтверждает: именно эта устойчивость приведёт к финалу, где всё сложится — не случайно, а закономерно.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj02,maj14,maj17',
 '["Жрица в прошлом: лучшие ваши решения приходили из тишины, а не из спешки. Так было и будет.","Умеренность в настоящем: сейчас важно выравнивать, а не ускорять. Энергия просится в наведение внутреннего порядка.","Звезда в будущем: из этого спокойствия родится ясная цель — и путь к ней окажется короче, чем казалось."]',
 'Неожиданный, но мудрый ответ: направьте энергию внутрь. Жрица напоминает, что ваши точные ходы всегда рождались из внутренней тишины. Умеренность в настоящем уточняет задачу: выровнять режим, разобрать завалы — в делах, в голове, в отношениях. Это не «потерянное время», это настройка инструмента перед концертом. Звезда в будущем обещает: когда внутри станет тихо, вы вдруг ясно увидите, куда идти, — и внешние шаги, которые раньше буксовали, начнут получаться с первого раза.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj04,maj10,maj19',
 '["Император в прошлом: там, где вы навели порядок, до сих пор всё работает. Структура — ваш конёк.","Колесо Фортуны в настоящем: вокруг открывается окно возможностей. Случайные встречи и предложения сейчас не случайны.","Солнце в будущем: сочетание вашей системности и подвернувшегося шанса даст яркий, заметный результат."]',
 'Карты советуют двухходовку. Император напоминает о вашей суперспособности: превращать хаос в систему. Колесо Фортуны в настоящем добавляет: прямо сейчас мимо вас проплывают возможности — новые люди, предложения, идеи. Энергию направьте на стык: ловите шанс и тут же ставьте его на рельсы — план, сроки, первый шаг в тот же день. Возможность без структуры испарится, структура без возможности заскучает. Солнце в будущем обещает: эта связка сработает громко — так, что заметят все.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj00,maj06,maj17',
 '["Шут в прошлом: ваши лучшие повороты начинались с решений, которые «разумные люди» не одобрили бы.","Влюблённые в настоящем: энергия сейчас утекает в сомнения между вариантами. Пора выбрать — и этим всё изменить.","Звезда в будущем: выбранный сердцем путь приведёт к цели, которая сейчас кажется почти несбыточной."]',
 'Расклад-развилка. Шут напоминает: вы уже выигрывали, ставя на «нелогичное», — ваша интуиция имеет хорошую статистику. Влюблённые в настоящем показывают, куда уходит сила: вы держите открытыми несколько дверей сразу, и это дорого стоит. Ответ на ваш вопрос прост и труден одновременно: направьте энергию в выбор. Один вариант, одно решение — и вся распылённая мощность соберётся в луч. Звезда в будущем обещает: путь, выбранный по-настоящему своим сердцем, окажется и самым удачливым.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj09,maj05,maj21',
 '["Отшельник в прошлом: свой главный опыт вы добыли сами — без подсказок и по собственным следам.","Иерофант в настоящем: сейчас время учиться у других или делиться своим знанием. Рост идёт через людей.","Мир в будущем: соединив свой путь с чужим опытом, вы придёте к результату быстрее и полнее."]',
 'Интересный поворот: карты советуют выйти из одиночного плавания. Отшельник отдаёт должное — вы самоучка в лучшем смысле, ваш опыт добыт честно. Но Иерофант в настоящем указывает направление для энергии: наставник, курс, сообщество, партнёр — рост сейчас лежит через других людей. Возможно, и наоборот: кому-то нужны именно ваши знания, и передача опыта откроет новое в вас самих. Мир в будущем подтверждает: в связке с правильными людьми ваш путь станет короче и радостнее.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj11,maj01,maj10',
 '["Справедливость в прошлом: вы навели честность в важном вопросе — расставили точки, даже если это было неприятно.","Маг в настоящем: сейчас идеальный момент для конкретного действия. Все ресурсы собраны, слово за вами.","Колесо Фортуны в будущем: первый же реальный шаг запустит цепочку удачных совпадений."]',
 'Очень деятельный расклад. Справедливость говорит: почву вы расчистили — долги закрыты, отношения прояснены, иллюзии распущены. Маг в настоящем не оставляет пространства для сомнений: энергию — в первое конкретное действие по главной цели. Не в планирование, не в обдумывание — в шаг, который можно сделать уже сегодня: письмо, звонок, заявка, черновик. Колесо Фортуны в будущем раскрывает секрет: вселенная сейчас отвечает именно на действия. Один шаг от вас — три шага навстречу от обстоятельств.'),

('Куда мне направить энергию, чтобы всё сложилось?', 'maj14,maj03,maj19',
 '["Умеренность в прошлом: вы научились не сгорать — дозировать себя, и это уже спасло вас не раз.","Императрица в настоящем: энергия просит творчества и живого дела — того, что растёт под руками.","Солнце в будущем: дело, в которое вы вложите душу без надрыва, принесёт и радость, и плоды."]',
 'Гармоничный ответ. Умеренность напоминает: вы уже умеете главное — работать вдолгую, не выгорая. Императрица в настоящем показывает, куда направить эту выверенную энергию: в живое созидание. Не в рутину и не в чужие ожидания, а в то, что растёт и отзывается: проект, дом, тело, отношения, ремесло. Критерий простой: после этого занятия сил больше, а не меньше. Солнце в будущем обещает: именно такое дело — тёплое, ваше — станет источником и дохода, и гордости.');
